    if not me.can_drive:
        return (0, 0)

    rr = sqrt(me.x * me.x + me.y * me.y)
    if rr > 5.35:
        b = bearing_to(0.0, 0.0)
        d = 99.0
    else:
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)

    w = me.weapons.get("front")
    rpm = 0
    if w:
        rpm = w.get("rpm", 0)

    base = 0.55 if rpm < 1800 else 0.9
    if d < 1.0:
        base = 0.6
    elif d < 1.45:
        base = 0.85

    if b > 100:
        return (0.8, -0.8)
    if b < -100:
        return (-0.8, 0.8)

    if b > 10:
        k = (b - 10) / 45.0
        if k > 1.0:
            k = 1.0
        l = base + k
        r = base - k
        if l > 1.0:
            l = 1.0
        if r < -1.0:
            r = -1.0
        return (l, r)

    if b < -10:
        k = (-b - 10) / 45.0
        if k > 1.0:
            k = 1.0
        l = base - k
        r = base + k
        if l < -1.0:
            l = -1.0
        if r > 1.0:
            r = 1.0
        return (l, r)

    return (base, base)


